      END_STATE();
    case 44:
      ACCEPT_TOKEN(sym_chars);
      END_STATE();
    case 45:
      ACCEPT_TOKEN(sym_escape);
      END_STATE();
    case 46:
      ACCEPT_TOKEN(sym_block_comment);
      END_STATE();
    case 47:
      ACCEPT_TOKEN(anon_sym_DOLLAREXTERNAL);
      END_STATE();
    case 48:
      ACCEPT_TOKEN(anon_sym_DOLLAREXTERN);
      if (lookahead == 'A') ADVANCE(10);
